use rk3588_boot_support::{BarrierOps,DelayUs,Mmio32};
pub const PMUMCU_STATUS_GATE:u64=0xFD7F_0A00;pub const PMUMCU_IDLE_STATUS:u64=0xFD58_A060;pub const PMUMCU_START_STATUS:u64=0xFD8D_4010;
pub const PMUMCU_IMAGE_MAGIC:u32=0x5F4D_4355;pub const PMUMCU_IMAGE_SENTINEL:u32=0xDEAD_BEAF;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct PmuMcuImage{pub src:u64,pub dst:u64,pub len:u32,pub entry:u32}
pub const PMUMCU_IMAGE:PmuMcuImage=PmuMcuImage{src:0x1000,dst:0xFF08_0000,len:0x17C00,entry:0xFF08_0000};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum PmuMcuError{IdleTimeout{status:u32},StartTimeout{status:u32}}
pub fn pmumcu_wait_idle<I:Mmio32+DelayUs>(io:&mut I)->Result<(),PmuMcuError>{if io.read32(PMUMCU_STATUS_GATE)&0x2000!=0{return Ok(())}let mut left=100_001u32;loop{let s=io.read32(PMUMCU_IDLE_STATUS);if s&0x680!=0{return Ok(())}if left==0{return Err(PmuMcuError::IdleTimeout{status:s})}left-=1;io.delay_us(1)}}
pub fn pmumcu_start<I:Mmio32+DelayUs+BarrierOps>(io:&mut I,entry:u32)->Result<(),PmuMcuError>{pmumcu_wait_idle(io)?;let v=io.read32(0xFE03_808C);io.write32(0xFE03_808C,v&0xFF00_FFFF);io.write32(0xFD58_2000,0x0008_0000);io.write32(0xFD58_2024,0xFFFF_0000|(entry>>16));io.write32(0xFD58_2028,0xFFFF_FF00);io.write32(PMUMCU_STATUS_GATE,0x7000_0000);io.dsb();io.isb();let mut left=500_000u32;loop{let s=io.read32(PMUMCU_START_STATUS);if s==0{return Ok(())}if left==0{return Err(PmuMcuError::StartTimeout{status:s})}left-=1;io.delay_us(1)}}
#[cfg(test)]mod tests{use super::*;struct M{gate:u32,idle:u32,start:u32,w:u32}impl Mmio32 for M{fn read32(&mut self,a:u64)->u32{match a{PMUMCU_STATUS_GATE=>self.gate,PMUMCU_IDLE_STATUS=>self.idle,PMUMCU_START_STATUS=>self.start,_=>0xffff_ffff}}fn write32(&mut self,a:u64,v:u32){self.w+=1;if a==PMUMCU_STATUS_GATE{self.gate=v}}}impl DelayUs for M{fn delay_us(&mut self,_:u32){}}impl BarrierOps for M{fn dsb(&mut self){}fn isb(&mut self){}}#[test]fn idle(){let mut m=M{gate:0,idle:0x680,start:0,w:0};pmumcu_start(&mut m,PMUMCU_IMAGE.entry).unwrap();assert!(m.w>=5);assert_eq!(PMUMCU_IMAGE.len,0x17C00);}}
